38	    static type = 'calendar';
39	    type = CalendarView.type;
40	
41	    /**
42	     * top/left line points
43	     */
44	    private _tlpoints: number[][];
45	
46	    /**
47	     * bottom/right line points
48	     */
49	    private _blpoints: number[][];
50	
51	    /**
52	     * first day of month
53	     */
54	    private _firstDayOfMonth: CalendarParsedDateInfo[];
55	
