61	    render(calendarModel: CalendarModel, ecModel: GlobalModel, api: ExtensionAPI) {
62	
63	        const group = this.group;
64	
65	        group.removeAll();
66	
67	        const coordSys = calendarModel.coordinateSystem;
68	
69	        // range info
70	        const rangeData = coordSys.getRangeInfo();
71	        const orient = coordSys.getOrient();
72	
73	        // locale
74	        const localeModel = ecModel.getLocaleModel();
75	
76	        this._renderDayRect(calendarModel, rangeData, group);
77	
78	        // _renderLines must be called prior to following function
79	        this._renderLines(calendarModel, rangeData, orient, group);
80	
81	        this._renderYearText(calendarModel, rangeData, orient, group);
82	
83	        this._renderMonthText(calendarModel, localeModel, orient, group);
84	
85	        this._renderWeekText(calendarModel, localeModel, rangeData, orient, group);
86	    }
87	
88	    // render day rect
89	    _renderDayRect(calendarModel: CalendarModel, rangeData: CalendarParsedDateRangeInfo, group: graphic.Group) {
90	        const coordSys = calendarModel.coordinateSystem;
91	        const itemRectStyleModel = calendarModel.getModel('itemStyle').getItemStyle();
92	        const sw = coordSys.getCellWidth();
93	        const sh = coordSys.getCellHeight();
94	
95	        for (let i = rangeData.start.time;
96	            i <= rangeData.end.time;
97	            i = coordSys.getNextNDay(i, 1).time
98	        ) {
99	
100	            const point = coordSys.dataToRect([i], false).tl;
101	
102	            // every rect
103	            const rect = new graphic.Rect({
104	                shape: {
105	                    x: point[0],
106	                    y: point[1],
107	                    width: sw,
108	                    height: sh
109	                },
110	                cursor: 'default',
111	                style: itemRectStyleModel
112	            });
113	
114	            group.add(rect);
115	        }
116	
117	    }
118	
119	    // render separate line
120	    _renderLines(
121	        calendarModel: CalendarModel,
122	        rangeData: CalendarParsedDateRangeInfo,
123	        orient: LayoutOrient,
124	        group: graphic.Group
125	    ) {
126	
127	        const self = this;
128	
129	        const coordSys = calendarModel.coordinateSystem;
130	
131	        const lineStyleModel = calendarModel.getModel(['splitLine', 'lineStyle']).getLineStyle();
132	        const show = calendarModel.get(['splitLine', 'show']);
133	
134	        const lineWidth = lineStyleModel.lineWidth;
135	
136	        this._tlpoints = [];
137	        this._blpoints = [];
138	        this._firstDayOfMonth = [];
139	        this._firstDayPoints = [];
140	
141	
142	        let firstDay = rangeData.start;
143	
144	        for (let i = 0; firstDay.time <= rangeData.end.time; i++) {
145	            addPoints(firstDay.formatedDate);
146	
147	            if (i === 0) {
148	                firstDay = coordSys.getDateInfo(rangeData.start.y + '-' + rangeData.start.m);
149	            }
150	
151	            const date = firstDay.date;
152	            date.setMonth(date.getMonth() + 1);
153	            firstDay = coordSys.getDateInfo(date);
154	        }
155	
156	        addPoints(coordSys.getNextNDay(rangeData.end.time, 1).formatedDate);
157	
158	        function addPoints(date: OptionDataValueDate) {
159	
160	            self._firstDayOfMonth.push(coordSys.getDateInfo(date));
161	            self._firstDayPoints.push(coordSys.dataToRect([date], false).tl);
162	
163	            const points = self._getLinePointsOfOneWeek(calendarModel, date, orient);
164	
165	            self._tlpoints.push(points[0]);
166	            self._blpoints.push(points[points.length - 1]);
167	
168	            show && self._drawSplitline(points, lineStyleModel, group);
169	        }
170	
171	
172	        // render top/left line
173	        show && this._drawSplitline(self._getEdgesPoints(self._tlpoints, lineWidth, orient), lineStyleModel, group);
174	
175	        // render bottom/right line
176	        show && this._drawSplitline(self._getEdgesPoints(self._blpoints, lineWidth, orient), lineStyleModel, group);
177	
178	    }
179	
180	    // get points at both ends
181	    _getEdgesPoints(points: number[][], lineWidth: number, orient: LayoutOrient) {
182	        const rs = [points[0].slice(), points[points.length - 1].slice()];
183	        const idx = orient === 'horizontal' ? 0 : 1;
184	
185	        // both ends of the line are extend half lineWidth
186	        rs[0][idx] = rs[0][idx] - lineWidth / 2;
187	        rs[1][idx] = rs[1][idx] + lineWidth / 2;
188	
189	        return rs;
190	    }
191	
192	    // render split line
193	    _drawSplitline(points: number[][], lineStyle: PathStyleProps, group: graphic.Group) {
194	
195	        const poyline = new graphic.Polyline({
196	            z2: 20,
197	            shape: {
198	                points: points
199	            },
200	            style: lineStyle
201	        });
202	
203	        group.add(poyline);
204	    }
205	
206	    // render month line of one week points
207	    _getLinePointsOfOneWeek(calendarModel: CalendarModel, date: OptionDataValueDate, orient: LayoutOrient) {
208	
209	        const coordSys = calendarModel.coordinateSystem;
210	        const parsedDate = coordSys.getDateInfo(date);
211	
212	        const points = [];
213	
214	        for (let i = 0; i < 7; i++) {
215	
216	            const tmpD = coordSys.getNextNDay(parsedDate.time, i);
217	            const point = coordSys.dataToRect([tmpD.time], false);
218	
219	            points[2 * tmpD.day] = point.tl;
220	            points[2 * tmpD.day + 1] = point[orient === 'horizontal' ? 'bl' : 'tr'];
221	        }
222	
223	        return points;
224	
225	    }
226	
227	    _formatterLabel<T extends { nameMap: string }>(
228	        formatter: string | ((params: T) => string),
229	        params: T
230	    ) {
231	
232	        if (isString(formatter) && formatter) {
233	            return formatTplSimple(formatter, params);
234	        }
235	
236	        if (isFunction(formatter)) {
237	            return formatter(params);
238	        }
239	
240	        return params.nameMap;
241	
242	    }
243	
244	    _yearTextPositionControl(
245	        textEl: graphic.Text,
246	        point: number[],
247	        orient: LayoutOrient,
248	        position: 'left' | 'right' | 'top' | 'bottom',
249	        margin: number
250	    ): TextProps {
251	
252	        let x = point[0];
253	        let y = point[1];
254	        let aligns: [ZRTextAlign, ZRTextVerticalAlign] = ['center', 'bottom'];
255	
256	        if (position === 'bottom') {
257	            y += margin;
258	            aligns = ['center', 'top'];
259	        }
260	        else if (position === 'left') {
261	            x -= margin;
262	        }
263	        else if (position === 'right') {
264	            x += margin;
265	            aligns = ['center', 'top'];
266	        }
267	        else { // top
268	            y -= margin;
269	        }
270	
271	        let rotate = 0;
272	        if (position === 'left' || position === 'right') {
273	            rotate = Math.PI / 2;
274	        }
275	
276	        return {
277	            rotation: rotate,
278	            x,
279	            y,
280	            style: {
281	                align: aligns[0],
282	                verticalAlign: aligns[1]
283	            }
284	        };
285	    }
286	
287	    // render year
288	    _renderYearText(
289	        calendarModel: CalendarModel,
290	        rangeData: CalendarParsedDateRangeInfo,
291	        orient: LayoutOrient,
292	        group: graphic.Group
293	    ) {
294	        const yearLabel = calendarModel.getModel('yearLabel');
295	
296	        if (!yearLabel.get('show')) {
297	            return;
298	        }
299	
300	        const margin = yearLabel.get('margin');
301	        let pos = yearLabel.get('position');
302	
303	        if (!pos) {
304	            pos = orient !== 'horizontal' ? 'top' : 'left';
305	        }
306	
307	        const points = [this._tlpoints[this._tlpoints.length - 1], this._blpoints[0]];
308	        const xc = (points[0][0] + points[1][0]) / 2;
309	        const yc = (points[0][1] + points[1][1]) / 2;
310	
311	        const idx = orient === 'horizontal' ? 0 : 1;
312	
313	        const posPoints = {
314	            top: [xc, points[idx][1]],
315	            bottom: [xc, points[1 - idx][1]],
316	            left: [points[1 - idx][0], yc],
317	            right: [points[idx][0], yc]
318	        };
319	
320	        let name = rangeData.start.y;
321	
322	        if (+rangeData.end.y > +rangeData.start.y) {
323	            name = name + '-' + rangeData.end.y;
324	        }
325	
326	        const formatter = yearLabel.get('formatter');
327	
328	        const params = {
329	            start: rangeData.start.y,
330	            end: rangeData.end.y,
331	            nameMap: name
332	        };
333	
334	        const content = this._formatterLabel(formatter, params);
335	
336	        const yearText = new graphic.Text({
337	            z2: 30,
338	            style: createTextStyle(yearLabel, {
339	                text: content
340	            })
341	        });
342	        yearText.attr(this._yearTextPositionControl(yearText, posPoints[pos], orient, pos, margin));
343	
344	        group.add(yearText);
345	    }
346	
347	    _monthTextPositionControl(
348	        point: number[],
349	        isCenter: boolean,
350	        orient: LayoutOrient,
351	        position: 'start' | 'end',
352	        margin: number
353	    ): TextStyleProps {
354	        let align: ZRTextAlign = 'left';
355	        let vAlign: ZRTextVerticalAlign = 'top';
356	        let x = point[0];
357	        let y = point[1];
358	
359	        if (orient === 'horizontal') {
360	            y = y + margin;
361	
362	            if (isCenter) {
363	                align = 'center';
364	            }
365	
366	            if (position === 'start') {
367	                vAlign = 'bottom';
368	            }
369	        }
370	        else {
371	            x = x + margin;
372	
373	            if (isCenter) {
374	                vAlign = 'middle';
375	            }
376	
377	            if (position === 'start') {
378	                align = 'right';
379	            }
380	        }
381	
382	        return {
383	            x: x,
384	            y: y,
385	            align: align,
386	            verticalAlign: vAlign
387	        };
388	    }
389	
390	    // render month and year text
391	    _renderMonthText(
392	        calendarModel: CalendarModel,
393	        localeModel: Model<LocaleOption>,
394	        orient: LayoutOrient,
395	        group: graphic.Group
396	    ) {
397	        const monthLabel = calendarModel.getModel('monthLabel');
398	
399	        if (!monthLabel.get('show')) {
400	            return;
401	        }
402	
403	        let nameMap = monthLabel.get('nameMap');
404	        let margin = monthLabel.get('margin');
405	        const pos = monthLabel.get('position');
406	        const align = monthLabel.get('align');
407	
408	        const termPoints = [this._tlpoints, this._blpoints];
409	
410	        if (!nameMap || isString(nameMap)) {
411	            if (nameMap) {
412	                // case-sensitive
413	                localeModel = getLocaleModel(nameMap as string) || localeModel;
414	            }
415	            // PENDING
416	            // for ZH locale, original form is `一月` but current form is `1月`
417	            nameMap = localeModel.get(['time', 'monthAbbr']) || [];
418	        }
419	
420	        const idx = pos === 'start' ? 0 : 1;
421	        const axis = orient === 'horizontal' ? 0 : 1;
422	        margin = pos === 'start' ? -margin : margin;
423	        const isCenter = (align === 'center');
424	
425	        for (let i = 0; i < termPoints[idx].length - 1; i++) {
426	
427	            const tmp = termPoints[idx][i].slice();
428	            const firstDay = this._firstDayOfMonth[i];
429	
430	            if (isCenter) {
431	                const firstDayPoints = this._firstDayPoints[i];
432	                tmp[axis] = (firstDayPoints[axis] + termPoints[0][i + 1][axis]) / 2;
433	            }
434	
435	            const formatter = monthLabel.get('formatter');
436	            const name = nameMap[+firstDay.m - 1];
437	            const params = {
438	                yyyy: firstDay.y,
439	                yy: (firstDay.y + '').slice(2),
440	                MM: firstDay.m,
441	                M: +firstDay.m,
442	                nameMap: name
443	            };
444	
445	            const content = this._formatterLabel(formatter, params);
446	
447	            const monthText = new graphic.Text({
448	                z2: 30,
449	                style: extend(
450	                    createTextStyle(monthLabel, {text: content}),
451	                    this._monthTextPositionControl(tmp, isCenter, orient, pos, margin)
452	                )
453	            });
454	
455	            group.add(monthText);
456	        }
457	    }
458	
459	    _weekTextPositionControl(
460	        point: number[],
461	        orient: LayoutOrient,
462	        position: 'start' | 'end',
463	        margin: number,
464	        cellSize: number[]
465	    ): TextStyleProps {
466	        let align: ZRTextAlign = 'center';
467	        let vAlign: ZRTextVerticalAlign = 'middle';
468	        let x = point[0];
469	        let y = point[1];
470	        const isStart = position === 'start';
471	
472	        if (orient === 'horizontal') {
473	            x = x + margin + (isStart ? 1 : -1) * cellSize[0] / 2;
474	            align = isStart ? 'right' : 'left';
475	        }
476	        else {
477	            y = y + margin + (isStart ? 1 : -1) * cellSize[1] / 2;
478	            vAlign = isStart ? 'bottom' : 'top';
479	        }
480	
481	        return {
482	            x: x,
483	            y: y,
484	            align: align,
485	            verticalAlign: vAlign
486	        };
487	    }
488	
489	    // render weeks
490	    _renderWeekText(
491	        calendarModel: CalendarModel,
492	        localeModel: Model<LocaleOption>,
493	        rangeData: CalendarParsedDateRangeInfo,
494	        orient: LayoutOrient,
495	        group: graphic.Group
496	    ) {
497	        const dayLabel = calendarModel.getModel('dayLabel');
498	
499	        if (!dayLabel.get('show')) {
500	            return;
501	        }
502	
503	        const coordSys = calendarModel.coordinateSystem;
504	        const pos = dayLabel.get('position');
505	        let nameMap = dayLabel.get('nameMap');
506	        let margin = dayLabel.get('margin');
507	        const firstDayOfWeek = coordSys.getFirstDayOfWeek();
508	
509	        if (!nameMap || isString(nameMap)) {
510	            if (nameMap) {
511	                // case-sensitive
512	                localeModel = getLocaleModel(nameMap as string) || localeModel;
513	            }
514	            // Use the first letter of `dayOfWeekAbbr` if `dayOfWeekShort` doesn't exist in the locale file
515	            const dayOfWeekShort = localeModel.get(['time', 'dayOfWeekShort' as any]);
516	            nameMap = dayOfWeekShort || map(
517	                localeModel.get(['time', 'dayOfWeekAbbr']),
518	                val => val[0]
519	            );
520	        }
521	
522	        let start = coordSys.getNextNDay(
523	            rangeData.end.time, (7 - rangeData.lweek)
524	        ).time;
525	
526	        const cellSize = [coordSys.getCellWidth(), coordSys.getCellHeight()];
527	        margin = parsePercent(margin, Math.min(cellSize[1], cellSize[0]));
528	
529	        if (pos === 'start') {
530	            start = coordSys.getNextNDay(
531	                rangeData.start.time, -(7 + rangeData.fweek)
532	            ).time;
533	            margin = -margin;
534	        }
535	
536	        for (let i = 0; i < 7; i++) {
537	
538	            const tmpD = coordSys.getNextNDay(start, i);
539	            const point = coordSys.dataToRect([tmpD.time], false).center;
540	            let day = i;
541	            day = Math.abs((i + firstDayOfWeek) % 7);
542	            const weekText = new graphic.Text({
543	                z2: 30,
544	                style: extend(
545	                    createTextStyle(dayLabel, {text: nameMap[day]}),
546	                    this._weekTextPositionControl(point, orient, pos, margin, cellSize)
547	                )
548	            });
549	
550	            group.add(weekText);
551	        }
552	    }
553	}
554	
555	export default CalendarView;

