import { createChart, removeChart } from '../test/ut/core/utHelper';

// Mirrors zrender's hit-testing logic: an element is effectively silent
// if itself or any ancestor (or host target) is silent.
function isEffectivelySilent(el: any): boolean {
    let cur = el;
    while (cur) {
        if (cur.silent) {
            return true;
        }
        cur = cur.__hostTarget || cur.parent;
    }
    return false;
}

function getCalendarLabelTexts(chart: ReturnType<typeof createChart>) {
    chart.getZr().refreshImmediately();
    const texts: { silent: boolean; text: string }[] = [];
    chart.getZr().storage.getDisplayList().forEach(function (el: any) {
        // zrender renders Text content as 'tspan' displayables in the display list.
        if (el.type === 'tspan') {
            texts.push({ silent: isEffectivelySilent(el), text: el.style && el.style.text });
        }
    });
    return texts;
}

describe('calendar-label-silent', function () {
    it('makes day/month/year label texts non-interactive when silent is true', function () {
        const chart = createChart();
        chart.setOption({
            calendar: {
                range: '2023-01',
                dayLabel: { silent: true },
                monthLabel: { silent: true },
                yearLabel: { silent: true }
            }
        });
        const texts = getCalendarLabelTexts(chart);
        expect(texts.length).toBeGreaterThan(0);
        texts.forEach(function (t) {
            expect(t.silent).toBe(true);
        });
        removeChart(chart);
    });

    it('keeps label texts interactive when silent is omitted', function () {
        const chart = createChart();
        chart.setOption({
            calendar: { range: '2023-01' }
        });
        const texts = getCalendarLabelTexts(chart);
        expect(texts.length).toBeGreaterThan(0);
        texts.forEach(function (t) {
            expect(t.silent).toBe(false);
        });
        removeChart(chart);
    });

    it('takes effect independently per label config', function () {
        const chart = createChart();
        chart.setOption({
            calendar: {
                range: '2023-01',
                yearLabel: { silent: true }
            }
        });
        const texts = getCalendarLabelTexts(chart);
        const yearTexts = texts.filter(t => t.text === '2023');
        const otherTexts = texts.filter(t => t.text !== '2023');
        expect(yearTexts.length).toBeGreaterThan(0);
        expect(otherTexts.length).toBeGreaterThan(0);
        yearTexts.forEach(t => expect(t.silent).toBe(true));
        otherTexts.forEach(t => expect(t.silent).toBe(false));
        removeChart(chart);
    });
});
